using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;
public static class Timber196Checks{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence196");const string Prior="Assets/Imported195b";
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static GameObject Prefab(string id)=>AssetDatabase.LoadAssetAtPath<GameObject>(Prior+"/small-"+id+".prefab");
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.08f,.09f,.10f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;}
 static void Shot(Camera c,string n){var im=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,n+".png"),im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}
 public static void Run(){Directory.CreateDirectory(Out);try{Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  var input=Path.Combine(Root,"Input196");var d=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));Check(d.mineTimberV1!=null&&d.assets.Length==43,"shared library read includes new and old");
  var built=MapSharedPropsBuilder.Build(input);Check(built.prefabs.Count==55&&built.prefabs.ContainsKey("mine_timber_frame")&&built.placed==25&&built.skipped==0,"complete55 prefab and25 placement integration");
  var oldPaths=Directory.GetFiles(Path.Combine(Root,"Assets/MapSharedPropsGenerated/Pilot 13"),"small-*.prefab");foreach(var file in oldPaths){var id=Path.GetFileNameWithoutExtension(file).Substring(6);Check(built.prefabs.ContainsKey(id),"old prefab retained "+id);var old=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 13/"+Path.GetFileName(file));var oldCount=old.GetComponentsInChildren<Collider>().Length;Check(built.prefabs[id].GetComponentsInChildren<Collider>().Length==oldCount,"old collider count "+id);if(oldCount>0)Check(ColliderSnapshot109.Capture(old)==ColliderSnapshot109.Capture(built.prefabs[id]),"old collider unchanged "+id);}
  AssetDatabase.SaveAssets();var scene=built.assetDirectory+"/timber196.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);var snap=ColliderSnapshot109.Capture(built.root);string rootName=built.root.name;Empty();EditorSceneManager.OpenScene(scene);var restored=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None).Single(x=>x.name==rootName);Check(ColliderSnapshot109.Capture(restored)==snap,"mixed scene collider persists");
  var rows=new List<string>();foreach(var kind in new[]{"non-solid","custom"}){Empty();var data=JsonUtility.FromJson<MineTimberV1.Data>(File.ReadAllText(Path.Combine(Root,"Input195/timber.json")));var a=data.assets[0];a.radius=kind=="non-solid"?0:.23f;a.height=2.2f;if(a.radius==0)a.circleColliders=null;else foreach(var c in a.circleColliders){c.radius=a.radius;c.height=a.height;c.center[0]=Mathf.Sign(c.center[0])*1.2f;}Check(MineTimberV1.Optional(data)!=null,"custom optional valid");string folder="Assets/Imported196-"+kind;Check(!AssetDatabase.IsValidFolder(folder),"fresh custom folder");AssetDatabase.CreateFolder("Assets","Imported196-"+kind);var dict=new Dictionary<string,GameObject>{{"mine_rail_straight",Prefab("mine_rail_straight")}};var root=new GameObject(kind);MineTimberV1.Build(Path.Combine(Root,"Input195"),folder,root.transform,dict,new SmallPropsV1.Data{mineTimberV1=data});var obj=dict["mine_timber_frame"];Check(obj.GetComponent<MeshFilter>().sharedMesh.vertexCount==1092,"custom keeps visual mesh");if(kind=="non-solid")Check(obj.GetComponents<Collider>().Length==0,"non-solid visual no collider");else{var cm=obj.GetComponent<MeshCollider>().sharedMesh;Check(Mathf.Abs(cm.bounds.max.y-2.2f)<1e-5&&Mathf.Abs(cm.bounds.max.x-1.43f)<1e-5,"custom radius height center honored");}rows.Add("{\"case\":\""+kind+"\",\"pass\":true}");}
  typeof(Timber195Checks).GetMethod("Load",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);Field();
  File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"formalPrefabs\":55,\"placed\":25,\"skipped\":0,\"sharedLibrary\":true,\"old54Retained\":true,\"all75Generated\":false,\"scene\":\""+scene+"\",\"custom\":["+string.Join(",",rows)+"],\"gpuMeasured\":false,\"player\":false}");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Field(){Empty();var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Timber196");Check(result.built,"existing mine");var frame=(GameObject)PrefabUtility.InstantiatePrefab(Prefab("mine_timber_frame"));frame.transform.position=new Vector3(12,0,10.5f);var c=new GameObject("offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.035f,.04f,.05f);c.fieldOfView=45;c.nearClipPlane=.03f;var hero=new GameObject("view anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;var lampPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 13/small-mine_wall_lantern.prefab");Check(lampPrefab,"existing lamp");GameObject lamp=null;
  foreach(var mode in new[]{"existing-light","wall-lamp"}){if(mode=="wall-lamp"){lamp=(GameObject)PrefabUtility.InstantiatePrefab(lampPrefab,result.root.transform);lamp.transform.position=new Vector3(10.84f,1.65f,9.7f);lamp.transform.rotation=Quaternion.Euler(0,90,0);var budget=result.root.GetComponentInChildren<RoomTorchBudget>();if(!budget)budget=result.root.AddComponent<RoomTorchBudget>();var fixtures=result.root.GetComponentsInChildren<RoomTorchInstance>();foreach(var f in fixtures)f.InitializePresentation();budget.Configure(fixtures);budget.SetFocus(hero);budget.TimeOverride=1;for(int i=0;i<40;i++)budget.Tick(.1f,hero.position);Check(budget.ActiveLights<=6,"existing lamp budget");}
   foreach(var view in new[]{"normal","close","reverse"}){var target=frame.transform.position+Vector3.up*1.3f;c.transform.position=view=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(view=="close"?new Vector3(.2f,.8f,-4.3f):new Vector3(-.2f,.8f,4.3f));c.transform.LookAt(view=="normal"?hero.position+Vector3.up*.5f:target);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);Shot(c,mode+"-"+view);}}
  File.WriteAllText(Path.Combine(Out,"field.json"),"{\"input\":\"Input123Mine\",\"existingLightViews\":3,\"supplementalExistingWallLanternViews\":3,\"oneAdditionalFixtureViaExistingBudget\":true,\"noExposureChange\":true,\"originalSceneUnchanged\":true}");
 }
